CREATE TRIGGER `payments_status_flow` BEFORE UPDATE ON `payments` WHEN (NEW.status IS NOT OLD.status AND NOT ((OLD.status = 'pending_verification' AND NEW.status IN ('confirmed', 'rejected')) OR (OLD.status = 'confirmed' AND NEW.status = 'withdrawn')))
    OR (OLD.provider IN ('razorpay', 'stripe') AND NEW.status IS NOT OLD.status AND NEW.status IN ('rejected', 'withdrawn'))
    OR ((OLD.status = 'pending_verification' AND NEW.status IN ('confirmed', 'rejected')) AND (NEW.verified_at IS NULL OR NOT (EXISTS (SELECT 1 FROM staff_users ou WHERE ou.id = NEW.verified_by AND ou.role = 'owner' AND ou.status = 'active') OR (OLD.provider IN ('razorpay') AND NEW.status = 'confirmed' AND NEW.verified_by IS NULL AND OLD.advance_receipt_id IS NULL AND NEW.advance_receipt_id IS NOT NULL
      AND EXISTS (SELECT 1 FROM advance_receipts gar WHERE gar.id = NEW.advance_receipt_id AND gar.client_id = OLD.client_id AND gar.currency = OLD.currency AND gar.amount_minor = OLD.amount_minor
        AND gar.received_on = OLD.received_on AND gar.reference_norm IS OLD.reference_norm AND gar.created_at = NEW.verified_at)))))
    OR ((OLD.status = 'confirmed' AND NEW.status = 'withdrawn') AND (NEW.withdrawn_at IS NULL OR NEW.withdraw_reason IS NULL OR trim(NEW.withdraw_reason) = '' OR NOT EXISTS (SELECT 1 FROM staff_users ou WHERE ou.id = NEW.withdrawn_by AND ou.role = 'owner' AND ou.status = 'active')))
    OR ((NEW.`verified_by` IS NOT OLD.`verified_by` OR NEW.`verified_at` IS NOT OLD.`verified_at`) AND NOT (OLD.status = 'pending_verification' AND NEW.status IN ('confirmed', 'rejected')))
    OR (NEW.decision_note IS NOT OLD.decision_note AND NOT (OLD.status = 'pending_verification' AND NEW.status IN ('confirmed', 'rejected')) AND NOT (NEW.`decision_note` IS NULL AND NEW.status IS OLD.status AND EXISTS (SELECT 1 FROM clients ec WHERE ec.id = OLD.client_id AND ec.anonymised_at IS NOT NULL)))
    OR ((NEW.`withdrawn_by` IS NOT OLD.`withdrawn_by` OR NEW.`withdrawn_at` IS NOT OLD.`withdrawn_at`) AND NOT (OLD.status = 'confirmed' AND NEW.status = 'withdrawn'))
    OR (NEW.withdraw_reason IS NOT OLD.withdraw_reason AND NOT (OLD.status = 'confirmed' AND NEW.status = 'withdrawn') AND NOT (NEW.`withdraw_reason` IS NULL AND NEW.status IS OLD.status AND EXISTS (SELECT 1 FROM clients ec WHERE ec.id = OLD.client_id AND ec.anonymised_at IS NOT NULL))) BEGIN SELECT RAISE(ABORT, 'payments_status_flow: a pending payment is confirmed or rejected once by the Owner, or a Razorpay payment confirmed by the system with its tax invoice; a confirmed one is withdrawn once by the Owner, with a reason; a gateway payment is never rejected or withdrawn'); END;
